WITH recent_accounts AS (SELECT * FROM accounts WHERE account_type IN ('CREDIT', 'LOAN', 'CHECKING') AND account_type != 'CREDIT' AND opened_date >= '2023-09-03'), accounts_stats AS (SELECT status, account_type, COUNT(CASE WHEN account_type = 'LOAN' THEN 1 END) AS loan_count, ROUND((100 * SUM(CASE WHEN status = 'FROZEN' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_frozen FROM recent_accounts GROUP BY status, account_type) SELECT status, account_type, loan_count, pct_frozen FROM accounts_stats WHERE pct_frozen < 43 ORDER BY pct_frozen DESC;
